algorithms.pseudocode:
every 10s for p in partitions:
  if p.ops_5min > 3500 writes or 5500 reads or p.size > 1TB:
    splitKey = p.loadHistogram.median()
    if splitKey not in (p.start, p.end):
      createChild(p.start, splitKey); createChild(splitKey, p.end)
      handoff via Raft config change; update routing table
